-- ════════════════════════════════════════════════════════════════════════════
-- 117 · GIP: saved Appointment Records
-- ════════════════════════════════════════════════════════════════════════════
-- The Appointment Record (the Province's landscape form listing the interns appointed together, generated by
-- gipAppointmentRecordHelper.ts) can now be saved, then listed on GIP → Appointments (View Appointments),
-- where it can be viewed, downloaded, printed again or deleted.
--
-- A record is a snapshot: the rows exactly as printed (name, address, designation, rate, period, area of
-- assignment, current status) plus the source of funds, designation, statement and signatories. Editing or
-- renewing an intern later doesn't change a saved record, so it stays what was signed. `gip_ids` links back to
-- the interns listed (no FK on an array; a deleted intern simply no longer resolves).
--
-- Access: Provincial PESO manages records; Municipal PESO, DOLE and admin may read them (like the other GIP tables).
-- Personal data (names, addresses) is read and exported only through the app, which logs each view / download
-- with privacyService (PRIVACY.md rule 5); rows have no single person to key the row-change audit trigger on.

BEGIN;

CREATE TABLE IF NOT EXISTS esmdd.gip_appointment_records (
  id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  -- 'PGAS', 'DOLE', or 'Mixed' when the record lists interns of both programs
  program          TEXT        NOT NULL CHECK (program IN ('PGAS', 'DOLE', 'Mixed')),
  source_of_funds  TEXT        NOT NULL CHECK (char_length(source_of_funds) BETWEEN 1 AND 200),
  designation      TEXT        NOT NULL CHECK (char_length(designation) BETWEEN 1 AND 150),
  statement        TEXT        NOT NULL CHECK (char_length(statement) <= 2000),
  -- [{ label, name, position }] × 4, printed under the statement
  signatories      JSONB       NOT NULL DEFAULT '[]'::JSONB CHECK (jsonb_typeof(signatories) = 'array'),
  -- [{ internId, name, address, designation, rate, periodStart, periodEnd, areaOfAssignment, currentStatus }]
  entries          JSONB       NOT NULL CHECK (jsonb_typeof(entries) = 'array' AND jsonb_array_length(entries) > 0),
  intern_count     INT         GENERATED ALWAYS AS (jsonb_array_length(entries)) STORED,
  gip_ids          UUID[]      NOT NULL DEFAULT '{}',
  created_by       UUID        REFERENCES auth.users(id) ON DELETE SET NULL DEFAULT auth.uid(),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE esmdd.gip_appointment_records IS
  'Saved GIP Appointment Records: a snapshot of the interns appointed together (rows as printed) with the source of funds, designation, statement and signatories.';

CREATE INDEX IF NOT EXISTS idx_gip_appointment_records_created_at
  ON esmdd.gip_appointment_records (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_gip_appointment_records_gip_ids
  ON esmdd.gip_appointment_records USING GIN (gip_ids);

-- ─── updated_at ────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION esmdd.set_gip_appointment_record_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_gip_appointment_record_updated_at ON esmdd.gip_appointment_records;
CREATE TRIGGER trg_gip_appointment_record_updated_at
  BEFORE UPDATE ON esmdd.gip_appointment_records
  FOR EACH ROW EXECUTE FUNCTION esmdd.set_gip_appointment_record_updated_at();

-- ─── Access ────────────────────────────────────────────────────────────────

GRANT SELECT, INSERT, UPDATE, DELETE ON esmdd.gip_appointment_records TO authenticated;
GRANT ALL ON esmdd.gip_appointment_records TO service_role;

ALTER TABLE esmdd.gip_appointment_records ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "provincial_peso_all" ON esmdd.gip_appointment_records;
CREATE POLICY "provincial_peso_all"
  ON esmdd.gip_appointment_records
  FOR ALL
  TO authenticated
  USING ((SELECT core.has_role('provincial_peso')))
  WITH CHECK ((SELECT core.has_role('provincial_peso')));

DROP POLICY IF EXISTS "oversight_select" ON esmdd.gip_appointment_records;
CREATE POLICY "oversight_select"
  ON esmdd.gip_appointment_records
  FOR SELECT
  TO authenticated
  USING ((SELECT core.has_role('municipal_peso', 'dole', 'admin')));

COMMIT;
